-- Create "instance_settings" table
CREATE TABLE "instance_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "value" bytea NOT NULL, "version" bigint NOT NULL, "updated_by" character varying NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create "org_settings" table
CREATE TABLE "org_settings" ("id" character varying NOT NULL, "org_id" character varying NOT NULL, "value" bytea NOT NULL, "version" bigint NOT NULL, "updated_by" character varying NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "org_settings_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "orgsetting_org_id" to table: "org_settings"
CREATE UNIQUE INDEX "orgsetting_org_id" ON "org_settings" ("org_id");
-- Create index "orgsetting_org_id_id" to table: "org_settings"
CREATE UNIQUE INDEX "orgsetting_org_id_id" ON "org_settings" ("org_id", "id");
